    steps = max(1, int(round(float(hold_s) / float(env.step_dt))))
    t = env.episode_length_buf.reshape(-1)
    since = getattr(env, "_genenv_success_since", None)
    if since is None or since.shape != t.shape:
        since = torch.full_like(t, -1)
    since = torch.where(now & ((since < 0) | (since >= t)), t, since)  # start, or restart after a reset
    since = torch.where(now, since, torch.full_like(t, -1))
    env._genenv_success_since = since
    return now & (since >= 0) & (t - since + 1 >= steps)

